-- The Unity Catalog SHOW surface.
SHOW CATALOGS;

SHOW CATALOGS LIKE 'pay*';

SHOW CONNECTIONS;

SHOW CREDENTIALS;

SHOW STORAGE CREDENTIALS;

SHOW SERVICE CREDENTIALS;

SHOW EXTERNAL LOCATIONS;

SHOW GROUPS;

SHOW GROUPS WITH USER `u`;

SHOW GROUPS WITH GROUP g LIKE 'a*';

SHOW POLICIES ON SCHEMA s;

SHOW EFFECTIVE POLICIES ON TABLE t;

SHOW PROCEDURES;

SHOW PROCEDURES IN s;

SHOW PROVIDERS LIKE 'other_org';

SHOW RECIPIENTS;

SHOW SHARES LIKE 'a*';

SHOW SHARES IN PROVIDER p;

SHOW TABLES DROPPED;

SHOW TABLES DROPPED IN c.s LIMIT 5;

SHOW USERS LIKE '*SEr*';

SHOW ALL IN SHARE s;

SHOW COLUMNS FROM t FROM s;

SHOW GRANTS ON SHARE shared_date;

SHOW GRANTS TO RECIPIENT a_corp;
